spec.query:
WITH if(has([${db:sqlstring}], '.*'), '.*', arrayStringConcat(arrayMap(v -> regexpQuoteMeta(v), [${db:sqlstring}]), '|')) AS demo_var_db,
if(has([${host_name:sqlstring}], '.*'), '.*', arrayStringConcat(arrayMap(v -> regexpQuoteMeta(v), [${host_name:sqlstring}]), '|')) AS demo_var_host_name,
if(has([${k8s_cluster_name:sqlstring}], '.*'), '.*', arrayStringConcat(arrayMap(v -> regexpQuoteMeta(v), [${k8s_cluster_name:sqlstring}]), '|')) AS demo_var_k8s_cluster_name,
if(has([${k8s_statefulset_name:sqlstring}], '.*'), '.*', arrayStringConcat(arrayMap(v -> regexpQuoteMeta(v), [${k8s_statefulset_name:sqlstring}]), '|')) AS demo_var_k8s_statefulset_name
SELECT sample.1 AS time, if(isFinite(sample.2), sample.2, NULL) AS "A",
  mapFromArrays(arrayMap(t -> t.1, tags), arrayMap(t -> t.2, tags)) AS labels
FROM prometheusQueryRange(demo_metrics, concat('round(
  sum by (postgresql_database_name) (
    rate(
      postgresql_blks_hit_total{
        postgresql_database_name=~', toJSONString(demo_var_db), ',
        k8s_cluster_name=~', toJSONString(demo_var_k8s_cluster_name), ', k8s_statefulset_name=~', toJSONString(demo_var_k8s_statefulset_name), ',
        host_name=~', toJSONString(demo_var_host_name), '
      }[', concat(toString(greatest(240, {step} * 4)), 's'), ']
    )
  )
  /
  (
    sum by (postgresql_database_name) (
      rate(
        postgresql_blks_hit_total{
          postgresql_database_name=~', toJSONString(demo_var_db), ',
          k8s_cluster_name=~', toJSONString(demo_var_k8s_cluster_name), ', k8s_statefulset_name=~', toJSONString(demo_var_k8s_statefulset_name), ',
          host_name=~', toJSONString(demo_var_host_name), '
        }[', concat(toString(greatest(240, {step} * 4)), 's'), ']
      )
    )
    +
    sum by (postgresql_database_name) (
      rate(
        postgresql_blks_read_total{
          postgresql_database_name=~', toJSONString(demo_var_db), ',
          k8s_cluster_name=~', toJSONString(demo_var_k8s_cluster_name), ', k8s_statefulset_name=~', toJSONString(demo_var_k8s_statefulset_name), ',
          host_name=~', toJSONString(demo_var_host_name), '
        }[', concat(toString(greatest(240, {step} * 4)), 's'), ']
      )
    )
  ) * 100,
  0.001
)'), toDateTime64('{start}', 3, 'UTC'), toDateTime64('{end}', 3, 'UTC'), toIntervalSecond({step}))
ARRAY JOIN samples AS sample
ORDER BY time
